    if (lo > hi) return -1;            // base case
    int mid = lo + (hi - lo) / 2;
    if (a[mid] == t) return mid;
    return a[mid] < t ? bs(a, mid+1, hi, t)
                      : bs(a, lo, mid-1, t);
