def bs(a, lo, hi, t):
    if lo > hi: return -1              # base case
    mid = (lo + hi) // 2
    if a[mid] == t: return mid
    return bs(a, mid+1, hi, t) if a[mid] < t else bs(a, lo, mid-1, t)

