int firstOcc(int a[], int n, int t) {
    int lo = 0, hi = n - 1, ans = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == t) { ans = mid; hi = mid - 1; } // keep going LEFT
        else if (a[mid] < t) lo = mid + 1;
        else hi = mid - 1;
    }
    return ans;
}

