def first_occurrence(a, t):
    lo, hi, ans = 0, n - 1, -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == t:
            ans = mid; hi = mid - 1    # keep hunting LEFT
        elif a[mid] < t: lo = mid + 1
        else: hi = mid - 1
    return ans
